    bag: <><path d="M5 8h14l-1 12a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 8Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/></>,
    arrow: <><path d="M5 12h14"/><path d="m13 5 7 7-7 7"/></>,
    plus: <><path d="M12 5v14"/><path d="M5 12h14"/></>,
    star: <path d="m12 3 2.6 6.3L21 10l-5 4.4L17.5 21 12 17.6 6.5 21 8 14.4 3 10l6.4-.7L12 3Z"/>,
    instagram: <><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor"/></>,
    twitter: <path d="M22 5.8a8.5 8.5 0 0 1-2.4.7 4.2 4.2 0 0 0 1.8-2.3 8.4 8.4 0 0 1-2.6 1A4.2 4.2 0 0 0 11.5 9a11.9 11.9 0 0 1-8.6-4.4 4.2 4.2 0 0 0 1.3 5.6 4.1 4.1 0 0 1-1.9-.5v.1A4.2 4.2 0 0 0 5.7 14a4.3 4.3 0 0 1-1.9.1 4.2 4.2 0 0 0 3.9 2.9A8.4 8.4 0 0 1 2 18.7a11.9 11.9 0 0 0 6.4 1.9c7.7 0 11.9-6.4 11.9-11.9v-.5A8.4 8.4 0 0 0 22 5.8Z"/>,
    pinterest: <><circle cx="12" cy="12" r="9"/><path d="M11 8c1-1 4-1 5 1 1 2 0 5-2 5s-3-1-2-3"/><path d="m11 12-2 8"/></>,
    youtube: <><rect x="3" y="6" width="18" height="12" rx="3"/><path d="m11 9 4 3-4 3z" fill="currentColor"/></>,
  };
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      {paths[name]}
    </svg>
  );
};

/* ---------- Components ---------- */
const Announce = () => (
  <div className="announce">
    <div className="container announce-inner">
      <span>Free carbon-neutral shipping over $75</span>
      <i className="dot" />
      <span>Members earn 2× points all week</span>
      <i className="dot" />
      <span>New: The Forest collection</span>
    </div>
  </div>
);

const Header = ({ cartCount, onCart }) => (
  <header className="header">
    <div className="container header-row">
      <a className="brand" href="#">
        <span className="brand-mark">M</span>
        Maren &amp; Co.
      </a>
      <nav className="nav">
        <a href="#" className="active">New</a>
        <a href="#">Women</a>
        <a href="#">Men</a>
        <a href="#">Home</a>
        <a href="#">Editorial</a>
        <a href="#">Sale</a>
