        <button className="icon-btn" aria-label="Cart" onClick={onCart}>
          <Icon name="bag" />
          {cartCount > 0 && <span className="cart-badge">{cartCount}</span>}
        </button>
      </div>
    </div>
  </header>
);

const Hero = () => (
  <section className="hero">
    <div className="container">
      <div className="hero-card">
        <div className="hero-text">
          <span className="eyebrow"><i className="pulse" /> Spring / Summer 26</span>
          <h1>Quiet pieces, <em>made to last</em>.</h1>
          <p>A capsule of considered essentials in natural fibers, hand-finished by makers we know by name.</p>
          <div className="hero-cta">
            <button className="btn btn-primary">Shop the collection <Icon name="arrow" size={16} /></button>
            <button className="btn btn-ghost">Watch the film</button>
          </div>
          <div className="hero-meta">
            <div><b>120+</b><span>New arrivals</span></div>
            <div><b>4.9★</b><span>12k reviews</span></div>
            <div><b>100%</b><span>Traceable</span></div>
          </div>
        </div>
        <div className="hero-visual" aria-hidden="true">
          <div className="hero-product" />
          <div className="hero-tag t1">
            <span className="swatch" />
            <span>Camel Linen<small>From $128</small></span>
          </div>
          <div className="hero-tag t2">
            <span className="swatch" />
            <span>Midnight<small>Just dropped</small></span>
          </div>
        </div>
      </div>
    </div>
  </section>
);

const Categories = () => (
  <section className="section" style={{ paddingTop: 8 }}>
    <div className="container">
      <div className="cats">
        {CATEGORIES.map(c => (
          <div key={c.id} className="cat">
            <div className="cat-thumb" style={{ background: c.bg }}>{c.icon}</div>
            <b>{c.name}</b>
            <span>{c.count}</span>
          </div>
        ))}
      </div>
    </div>
  </section>
);

const ProductCard = ({ p, isFav, onFav, onAdd }) => (
  <article className="product">
    <div className="product-media">
      <div className="art" style={{ background: p.bg }}>{p.art}</div>
      {p.badge === "sale" && <span className="badge sale">−{Math.round((1 - p.price / p.was) * 100)}%</span>}
      {p.badge === "new" && <span className="badge new">New</span>}
      {p.badge === "eco" && <span className="badge eco">Eco</span>}
      <button className={`fav ${isFav ? "is-fav" : ""}`} onClick={() => onFav(p.id)} aria-label="Add to wishlist">
        <Icon name="heart" size={18} />
      </button>
      <div className="swatches">
        {p.swatches.map((s, i) => <i key={i} style={{ background: s }} />)}
      </div>
      <button className="quick-add" onClick={() => onAdd(p)}>
        <Icon name="plus" size={14} /> Quick add
      </button>
    </div>
    <div className="product-body">
      <span className="product-cat">{p.category}</span>
      <span className="product-name">{p.name}</span>
      <div className="product-meta">
        <span className="price">${p.price}{p.was && <s>${p.was}</s>}</span>
        <span className="rating"><span className="star">★</span>{p.rating} <span style={{color:"var(--muted)"}}>({p.reviews})</span></span>
      </div>
    </div>
  </article>
);

const FeaturedProducts = ({ favs, onFav, onAdd }) => {
  const [filter, setFilter] = useState("All");
  const items = useMemo(() => {
    switch (filter) {
      case "Bestsellers": return PRODUCTS.filter(p => p.tags.includes("bestseller"));
      case "New Arrivals": return PRODUCTS.filter(p => p.tags.includes("new"));
      case "Limited Edition": return PRODUCTS.filter(p => p.tags.includes("limited"));
      case "Under $100": return PRODUCTS.filter(p => p.price < 100);
      default: return PRODUCTS;
    }
  }, [filter]);

  return (
    <section className="section">
      <div className="container">
        <div className="section-head">
          <div>
            <span className="eyebrow"><i className="pulse" /> Featured</span>
            <h2 style={{marginTop:8}}>This week's favorites</h2>
            <p className="sub">Our most-loved pieces, curated by the studio team.</p>
          </div>
          <div className="head-actions">
            <a href="#" className="chip-link">View all <Icon name="arrow" size={14} /></a>
          </div>
        </div>
        <div className="pills">
          {FILTERS.map(f => (
            <button key={f} className={`pill ${filter === f ? "active" : ""}`} onClick={() => setFilter(f)}>{f}</button>
          ))}
        </div>
        <div className="products">
          {items.map(p => (
            <ProductCard key={p.id} p={p} isFav={favs.includes(p.id)} onFav={onFav} onAdd={onAdd} />
          ))}
        </div>
      </div>
    </section>
  );
};

const Countdown = () => {
  const [t, setT] = useState({ d: 2, h: 14, m: 32, s: 9 });
  useEffect(() => {
    const id = setInterval(() => {
      setT(prev => {
        let { d, h, m, s } = prev;
        s -= 1;
        if (s < 0) { s = 59; m -= 1; }
        if (m < 0) { m = 59; h -= 1; }
        if (h < 0) { h = 23; d -= 1; }
        if (d < 0) { d = 0; h = 0; m = 0; s = 0; }
        return { d, h, m, s };
      });
    }, 1000);
    return () => clearInterval(id);
  }, []);
  const pad = n => String(n).padStart(2, "0");
  return (
    <div className="countdown" aria-label="Time remaining">
      <span>{pad(t.d)}<small>Days</small></span>
      <span>{pad(t.h)}<small>Hrs</small></span>
      <span>{pad(t.m)}<small>Min</small></span>
      <span>{pad(t.s)}<small>Sec</small></span>
    </div>
  );
};

const Deals = () => (
  <section className="section">
    <div className="container">
      <div className="section-head">
        <div>
          <span className="eyebrow"><i className="pulse" /> Deals</span>
          <h2 style={{marginTop:8}}>Worth a second look</h2>
          <p className="sub">Curated offers, never on quality.</p>
        </div>
        <a href="#" className="chip-link">All offers <Icon name="arrow" size={14} /></a>
      </div>
      <div className="deals">
        {DEALS.map(d => (
          <div key={d.id} className={`deal ${d.className}`}>
            <div>
              <span className="deal-badge">{d.badge}</span>
              <h3 style={{marginTop:14}}>{d.title}</h3>
              <p>{d.desc}</p>
