    </div>
  </section>
);

const Editorial = () => (
  <section className="section">
    <div className="container">
      <div className="editorial-head">
        <span className="eyebrow"><i className="pulse" /> The Journal</span>
        <h2>Stories, guides &amp; field notes</h2>
      </div>
      <div className="articles">
        {ARTICLES.map(a => (
          <article key={a.id} className="article">
            <div className="article-media">
              <div className="cover" style={{ background: a.bg }}>{a.art}</div>
              <span className="article-tag">{a.tag}</span>
            </div>
            <div className="article-body">
              <div className="article-meta">{a.date}</div>
              <h3>{a.title}</h3>
              <p>{a.excerpt}</p>
              <span className="read-more">Read article <Icon name="arrow" size={14} /></span>
            </div>
          </article>
        ))}
      </div>
    </div>
  </section>
);

const Split = () => (
  <section className="section">
    <div className="container">
      <div className="split">
        <div className="split-text">
          <span className="eyebrow" style={{color:"#ffb29c"}}><i className="pulse" /> Membership</span>
          <h2>Join Maren Circle.</h2>
          <p>Early access to drops, member-only pricing, and a complimentary gift on your birthday. No annual fee.</p>
          <button className="btn btn-light">Become a member <Icon name="arrow" size={16} /></button>
        </div>
        <div className="split-visual" aria-hidden="true">
          <div className="planet" />
        </div>
      </div>
    </div>
  </section>
);

const Trust = () => (
  <section className="container">
    <div className="trust">
      {TRUST.map((t, i) => (
        <div key={i} className="trust-item">
          <div className="trust-icon">{t.icon}</div>
          <div>
            <b>{t.title}</b>
            <span>{t.sub}</span>
          </div>
        </div>
      ))}
    </div>
  </section>
);

const Newsletter = ({ onSubscribe }) => {
  const [email, setEmail] = useState("");
  const submit = (e) => {
    e.preventDefault();
    if (!email.includes("@")) return;
    onSubscribe(email);
    setEmail("");
  };
  return (
    <section className="container">
      <div className="newsletter">
        <div>
          <h2>A quieter inbox, on purpose.</h2>
          <p>One thoughtful email each week — new arrivals, restocks and reading from the studio.</p>
        </div>
        <div>
          <form className="subscribe" onSubmit={submit}>
            <input type="email" placeholder="you@domain.com" value={email} onChange={e => setEmail(e.target.value)} aria-label="Email" />
            <button type="submit">Subscribe <Icon name="arrow" size={14} /></button>
          </form>
          <div className="subscribe-note">Unsubscribe anytime. We never share your address.</div>
        </div>
      </div>
    </section>
  );
};

const Footer = () => (
  <footer>
