      <div className="foot-grid">
        <div className="foot-brand">
          <a className="brand" href="#"><span className="brand-mark">M</span> Maren &amp; Co.</a>
          <p>Considered objects for everyday life, made by hands we know.</p>
          <div className="socials">
            <a href="#" aria-label="Instagram"><Icon name="instagram" size={16} /></a>
            <a href="#" aria-label="Pinterest"><Icon name="pinterest" size={16} /></a>
            <a href="#" aria-label="Twitter"><Icon name="twitter" size={16} /></a>
            <a href="#" aria-label="YouTube"><Icon name="youtube" size={16} /></a>
          </div>
        </div>
        <div className="foot-col">
          <h5>Shop</h5>
          <ul><li><a href="#">New In</a></li><li><a href="#">Women</a></li><li><a href="#">Men</a></li><li><a href="#">Home</a></li><li><a href="#">Sale</a></li></ul>
        </div>
        <div className="foot-col">
          <h5>Help</h5>
          <ul><li><a href="#">Shipping</a></li><li><a href="#">Returns</a></li><li><a href="#">Size guide</a></li><li><a href="#">Contact</a></li><li><a href="#">FAQ</a></li></ul>
        </div>
        <div className="foot-col">
          <h5>Company</h5>
          <ul><li><a href="#">About</a></li><li><a href="#">Sustainability</a></li><li><a href="#">Stores</a></li><li><a href="#">Careers</a></li><li><a href="#">Press</a></li></ul>
        </div>
        <div className="foot-col">
          <h5>Legal</h5>
          <ul><li><a href="#">Privacy</a></li><li><a href="#">Terms</a></li><li><a href="#">Accessibility</a></li><li><a href="#">Cookies</a></li></ul>
        </div>
      </div>
      <div className="foot-bot">
        <span>© 2026 Maren &amp; Co. — All rights reserved.</span>
        <div className="pay">
          <span>VISA</span><span>MC</span><span>AMEX</span><span>PAYPAL</span><span>APPLE</span>
        </div>
      </div>
    </div>
  </footer>
);

const Toast = ({ msg, show }) => (
  <div className={`toast ${show ? "show" : ""}`}>
    <span className="check">✓</span> {msg}
  </div>
);

/* ---------- App ---------- */
const App = () => {
  const [favs, setFavs] = useState([3, 5]);
  const [cart, setCart] = useState([]);
  const [toast, setToast] = useState({ msg: "", show: false });
  const tRef = useRef(null);

  const flash = (msg) => {
    setToast({ msg, show: true });
    clearTimeout(tRef.current);
    tRef.current = setTimeout(() => setToast(t => ({ ...t, show: false })), 2200);
  };

  const handleFav = (id) => {
    setFavs(prev => {
      const next = prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id];
      flash(prev.includes(id) ? "Removed from wishlist" : "Saved to wishlist");
      return next;
    });
  };
  const handleAdd = (p) => {
    setCart(prev => [...prev, p.id]);
    flash(`${p.name} added to bag`);
  };
  const handleSubscribe = (email) => flash(`Welcome — confirmation sent to ${email}`);

  return (
    <>
      <Announce />
      <Header cartCount={cart.length} onCart={() => flash(`${cart.length} item${cart.length === 1 ? "" : "s"} in your bag`)} />
      <main>
        <Hero />
        <Categories />
        <FeaturedProducts favs={favs} onFav={handleFav} onAdd={handleAdd} />
        <Deals />
        <Split />
        <Editorial />
        <Trust />
        <Newsletter onSubscribe={handleSubscribe} />
      </main>
      <Footer />
      <Toast msg={toast.msg} show={toast.show} />
    </>
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
